DROP TABLE IF EXISTS MED;
CREATE TABLE MED (ID INTEGER PRIMARY KEY, NAME VARCHAR(128), INN VARCHAR(128));
DROP TABLE IF EXISTS PROD;
CREATE TABLE PROD (PID INTEGER PRIMARY KEY, MED_ID INTEGER REFERENCES MED(ID), PCODE VARCHAR(128), INN VARCHAR(128), CONCENTRATION VARCHAR(128), DESCRIPTION VARCHAR(256));
DROP TABLE IF EXISTS PRICE;
CREATE TABLE PRICE (ID SERIAL PRIMARY KEY, MED_ID INTEGER REFERENCES MED(ID), YEAR INT, PMIN DOUBLE PRECISION, PMAX DOUBLE PRECISION, PAVG DOUBLE PRECISION, PWGT DOUBLE PRECISION );
